window.__finlexDocLoaded(10053,{"id":10053,"articles":[{"id":1000121,"no":"Overview","heading":"Scope & Key Requirements (Public Summary)","text":"Sets out the International Independence Standards applicable to audit and review engagements, including public interest entity (PIE) definitions, fee-related provisions, non-assurance services restrictions, and partner rotation.","seq":0},{"id":1000122,"no":"IESBA Sec 400–600","heading":"Audit & Review Independence: PIEs, Fees, NAS & Partner Rotation","text":"• Independence of Mind and Independence in Appearance required throughout the engagement period and period covered by the financial statements (Section 400).\n• Public Interest Entities — PIEs (Section 400.17): expanded definition covering publicly traded entities, banks, insurers, and entities holding assets in a fiduciary capacity.\n• Fee-related provisions (Section 410): public fee transparency for PIEs and fee-dependency thresholds (>15% for 2 consecutive years triggers mandatory pre-issuance EQR; >15% for 5 consecutive years triggers resignation for PIEs).\n• Non-Assurance Services — NAS (Section 600): prohibits creating a self-review threat for PIE audit clients (no materiality qualifier) and requires TCWG concurrence; Key Audit Partner rotation limited to 7 years on / 5 years cooling-off for PIE engagement partners (Section 540).","seq":1},{"id":1000123,"no":"Official Access","heading":"Official Handbook & Reference Entry","text":"Official source (IESBA 2026 Handbook): https://www.ethicsboard.org/publications/2026-handbook-international-code-ethics-professional-accountants\nStatus: in_force. Detailed paragraph-level summaries and practice notes can be expanded incrementally.","seq":2}]});
